"""A Bloom filter: 'definitely not present' or 'possibly present', never a false 'not present'."""
from __future__ import annotations

import hashlib
import json
import math


class BloomFilter:
    def __init__(self, n_bits: int, n_hashes: int, bits: bytearray | None = None) -> None:
        self.n_bits, self.n_hashes = n_bits, n_hashes
        self.bits = bits if bits is not None else bytearray((n_bits + 7) // 8)

    @classmethod
    def for_keys(cls, n_keys: int, bits_per_key: int = 10) -> "BloomFilter":
        """Size the filter for n_keys; k = bits_per_key x ln 2 hashes minimises false positives (7 for 10)."""
        return cls(max(8, n_keys * bits_per_key), max(1, round(bits_per_key * math.log(2))))

    def _positions(self, key: str) -> list[int]:
        """k bit positions by double hashing: h1 + i*h2 for i in 0..k-1, from one SHA-256 digest."""
        d = hashlib.sha256(key.encode("utf-8")).digest()
        h1, h2 = int.from_bytes(d[:8], "big"), int.from_bytes(d[8:16], "big") | 1
        return [(h1 + i * h2) % self.n_bits for i in range(self.n_hashes)]

    def add(self, key: str) -> None:
        raise NotImplementedError("TODO: set the bit at each position")

    def might_contain(self, key: str) -> bool:
        raise NotImplementedError("TODO: True only if every position's bit is set")

    def to_json(self) -> str:
        return json.dumps({"n_bits": self.n_bits, "n_hashes": self.n_hashes, "bits": self.bits.hex()})

    @classmethod
    def from_json(cls, text: str) -> "BloomFilter":
        d = json.loads(text)
        return cls(d["n_bits"], d["n_hashes"], bytearray.fromhex(d["bits"]))

