"""Multi-version concurrency control in miniature, following PostgreSQL's design.

Every write adds a row version. A version records xmin (the transaction that created it) and xmax (the
transaction that deleted or replaced it; 0 if none). A snapshot records which transactions it must treat
as not yet committed. Read committed takes a new snapshot for every statement; repeatable read takes one
when the transaction begins and keeps it (snapshot isolation).
"""
from __future__ import annotations

from dataclasses import dataclass


class SerializationFailure(Exception):
    """Like PostgreSQL's 'could not serialize access due to concurrent update' (SQLSTATE 40001)."""


class WouldBlock(Exception):
    """Another open transaction is changing this row. A real database would wait for it to finish."""


@dataclass
class Version:
    key: str
    value: object
    xmin: int
    xmax: int = 0


@dataclass(frozen=True)
class Snapshot:
    next_xid: int             # transactions with this ID or higher hadn't started: invisible
    running: frozenset        # transactions that had started but not finished: invisible


class Database:
    def __init__(self) -> None:
        self.versions: list[Version] = []           # in creation order, so a key's newest version is last
        self.status: dict[int, str] = {}            # xid -> "running", "committed" or "aborted"
        self.open: dict[int, "Transaction"] = {}
        self.next_xid = 1

    def begin(self, isolation: str = "read committed") -> "Transaction":
        txn = Transaction(self, self.next_xid, isolation)
        self.status[txn.xid] = "running"
        self.open[txn.xid] = txn
        self.next_xid += 1
        if isolation == "repeatable read":
            txn.snapshot = self.take_snapshot()
        return txn

    def take_snapshot(self) -> Snapshot:
        return Snapshot(self.next_xid, frozenset(x for x, s in self.status.items() if s == "running"))

    def committed_for(self, xid: int, snap: Snapshot) -> bool:
        """Did xid commit, as far as this snapshot is concerned?"""
        return self.status.get(xid) == "committed" and xid < snap.next_xid and xid not in snap.running

    def visible(self, v: Version, snap: Snapshot, me: int) -> bool:
        """Can transaction `me`, reading with `snap`, see version v?
        It must have been created by `me` or by a transaction committed for the snapshot, and not deleted by
        `me` or by a transaction committed for the snapshot."""
        raise NotImplementedError("TODO: two conditions, each using committed_for (or xid == me)")

    def current(self, key: str) -> Version | None:
        """The key's newest version that wasn't created by an aborted transaction."""
        for v in reversed(self.versions):
            if v.key == key and self.status.get(v.xmin) != "aborted":
                return v
        return None

    def vacuum(self) -> int:
        """Remove versions that no open snapshot can see any more; return how many were removed."""
        held = [t.snapshot for t in self.open.values() if t.snapshot is not None]

        def needed(v: Version) -> bool:
            if self.status.get(v.xmin) == "aborted":
                return False
            if v.xmax == 0 or self.status.get(v.xmax) != "committed":
                return True
            return any(not self.committed_for(v.xmax, s) for s in held)   # an old snapshot still sees it

        before = len(self.versions)
        self.versions = [v for v in self.versions if needed(v)]
        return before - len(self.versions)


class Transaction:
    def __init__(self, db: Database, xid: int, isolation: str) -> None:
        self.db, self.xid, self.isolation = db, xid, isolation
        self.snapshot: Snapshot | None = None

    def _snap(self) -> Snapshot:
        return self.snapshot if self.snapshot is not None else self.db.take_snapshot()

    def read(self, key: str) -> object:
        snap = self._snap()
        for v in reversed(self.db.versions):
            if v.key == key and self.db.visible(v, snap, self.xid):
                return v.value
        return None

    def write(self, key: str, value: object) -> None:
        """Replace (or insert) the key's value: set xmax on the current version and add a new one.

        If another open transaction created or replaced the current version, raise WouldBlock. Under repeatable
        read, if the current version was created or replaced by a transaction this snapshot can't see as
        committed (it committed after the snapshot), raise SerializationFailure: first updater wins.
        Under read committed, carry on: the write lands on top of the newest committed version.
        """
        cur = self.db.current(key)
        if cur is not None:
            others = [x for x in (cur.xmin, cur.xmax) if x not in (0, self.xid)]
            if any(self.db.status.get(x) == "running" for x in others):
                raise WouldBlock(f"transaction {self.xid} would wait for another writer of {key!r}")
            raise NotImplementedError("TODO: under repeatable read, refuse if the current version isn't visible")
        self.db.versions.append(Version(key, value, self.xid))

    def commit(self) -> None:
        self.db.status[self.xid] = "committed"
        del self.db.open[self.xid]

    def abort(self) -> None:
        self.db.status[self.xid] = "aborted"
        for v in self.db.versions:
            if v.xmax == self.xid:
                v.xmax = 0                               # the replaced versions are current again
        del self.db.open[self.xid]

