"""An exclusive-lock manager with a waits-for graph and deadlock detection."""
from __future__ import annotations


class LockManager:
    def __init__(self) -> None:
        self.holder: dict[str, str] = {}             # resource -> transaction holding it
        self.waiting: dict[str, str] = {}            # transaction -> resource it waits for
        self.started: dict[str, int] = {}            # transaction -> start order, for choosing a victim

    def acquire(self, txn: str, resource: str) -> str:
        self.started.setdefault(txn, len(self.started))
        owner = self.holder.get(resource)
        if owner is None or owner == txn:
            self.holder[resource] = txn
            return "granted"
        self.waiting[txn] = resource
        return "waiting"

    def release_all(self, txn: str) -> list[str]:
        """End txn: free its locks and grant each to the first transaction waiting for it."""
        self.waiting.pop(txn, None)
        granted = []
        for resource in [r for r, t in self.holder.items() if t == txn]:
            del self.holder[resource]
            for waiter, wanted in list(self.waiting.items()):
                if wanted == resource:
                    del self.waiting[waiter]
                    self.holder[resource] = waiter
                    granted.append(f"{waiter} gets {resource}")
                    break
        return granted

    def waits_for(self) -> dict[str, set[str]]:
        """An edge from each waiting transaction to the transaction holding what it wants."""
        return {t: {self.holder[r]} for t, r in self.waiting.items() if r in self.holder}

    def victim(self, cycle: list[str]) -> str:
        """This manager's policy: abort the youngest transaction in the cycle (PostgreSQL instead aborts the
        transaction whose deadlock check found the cycle)."""
        return max(cycle[:-1], key=lambda t: self.started[t])


def find_cycle(graph: dict[str, set[str]]) -> list[str] | None:
    """Return one cycle as [t1, t2, ..., t1], or None if the graph has no cycle.
    Depth-first search, tracking the transactions on the current path."""
